 # Lab 5 now improves the launch office, not a social calendar that no longer exists in Lab 2.
 def revise(value):
  if isinstance(value,str): return value.replace('outputs/lab02/content-calendar-v2.csv','outputs/lab05/office-action-plan.csv').replace('outputs/lab02/content-calendar.csv','outputs/lab02/analysis.json').replace('content-calendar-v2.csv','office-action-plan.csv').replace('the content calendar','the launch-office action plan').replace('content-calendar.csv','office-action-plan.csv')
  if isinstance(value,list): return [revise(x) for x in value]
  if isinstance(value,tuple): return tuple(revise(x) for x in value)
  if isinstance(value,dict): return {k:revise(v) for k,v in value.items()}
  return value
 LABS[4]=revise(LABS[4])

